        "titolo_orig": "Artemis crew home safely after completing historic mission to the Moon",
        "testo_it": "Gli astronauti della missione Artemis 2 rientrano sulla Terra dopo il volo lunare.",
        "priorita": "Alta",
        "id_gruppo": 4,
        "link": "https://www.bbc.com/news/articles/cr51z54d5rpo?at_medium=RSS&at_campaign=rss",
